CREATE TABLE users (
 id VARCHAR(64) PRIMARY KEY, wechat_identity VARCHAR(128) UNIQUE, nickname VARCHAR(80), avatar_ref VARCHAR(255),
 role ENUM('user','admin') NOT NULL DEFAULT 'user', status ENUM('active','disabled') NOT NULL DEFAULT 'active', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE areas (id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL,region JSON NOT NULL,version INT NOT NULL DEFAULT 1);
CREATE TABLE cats (id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL,area_id VARCHAR(64) NOT NULL,aliases JSON NOT NULL,photo_refs JSON NOT NULL,sex ENUM('male','female','unknown') NOT NULL DEFAULT 'unknown',appearance TEXT,personality TEXT,version INT NOT NULL DEFAULT 1,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),FOREIGN KEY(area_id) REFERENCES areas(id),INDEX(area_id),INDEX(name));
CREATE TABLE topics (id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,status ENUM('active','inactive') NOT NULL DEFAULT 'active',version INT NOT NULL DEFAULT 1);
CREATE TABLE posts (id VARCHAR(64) PRIMARY KEY,author_id VARCHAR(64) NOT NULL,body TEXT NOT NULL,status ENUM('published','hidden','deleted') NOT NULL DEFAULT 'published',request_key VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(author_id) REFERENCES users(id),UNIQUE(author_id,request_key),INDEX(status,created_at,id));
CREATE TABLE assets (id VARCHAR(64) PRIMARY KEY,owner_id VARCHAR(64) NOT NULL,purpose ENUM('post','avatar','cat') NOT NULL,storage_key VARCHAR(255) NOT NULL UNIQUE,mime_type VARCHAR(80) NOT NULL,byte_size INT NOT NULL,status ENUM('pending','ready') NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE post_images (post_id VARCHAR(64) NOT NULL,image_ref VARCHAR(64) NOT NULL,sort_order INT NOT NULL,PRIMARY KEY(post_id,sort_order),UNIQUE(post_id,image_ref),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(image_ref) REFERENCES assets(id),CHECK(sort_order BETWEEN 0 AND 8));
CREATE TABLE post_cats (post_id VARCHAR(64) NOT NULL,cat_id VARCHAR(64) NOT NULL,PRIMARY KEY(post_id,cat_id),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(cat_id) REFERENCES cats(id),INDEX(cat_id,post_id));
CREATE TABLE post_topics (post_id VARCHAR(64) NOT NULL,topic_id VARCHAR(64) NOT NULL,PRIMARY KEY(post_id,topic_id),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(topic_id) REFERENCES topics(id),INDEX(topic_id,post_id));
CREATE TABLE comments (id VARCHAR(64) PRIMARY KEY,post_id VARCHAR(64) NOT NULL,author_id VARCHAR(64) NOT NULL,body TEXT NOT NULL,reply_to_id VARCHAR(64),request_key VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(author_id,request_key),UNIQUE(post_id,id),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(post_id,reply_to_id) REFERENCES comments(post_id,id),INDEX(post_id,created_at));
CREATE TABLE likes (user_id VARCHAR(64) NOT NULL,post_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,post_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id),INDEX(post_id));
CREATE TABLE notifications (id VARCHAR(64) PRIMARY KEY,recipient_id VARCHAR(64) NOT NULL,post_id VARCHAR(64) NOT NULL,comment_id VARCHAR(64) NOT NULL,type ENUM('comment','reply') NOT NULL,read_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(recipient_id,comment_id),FOREIGN KEY(recipient_id) REFERENCES users(id),FOREIGN KEY(post_id,comment_id) REFERENCES comments(post_id,id),INDEX(recipient_id,read_at,created_at));
CREATE TABLE admin_logs (id VARCHAR(64) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,object_type ENUM('post','cat','area','topic') NOT NULL,object_id VARCHAR(64) NOT NULL,action VARCHAR(64) NOT NULL,reason TEXT,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE idempotency_keys (actor_id VARCHAR(64) NOT NULL,scope VARCHAR(80) NOT NULL,request_key VARCHAR(80) NOT NULL,request_hash CHAR(64) NOT NULL,response_json JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(actor_id,scope,request_key),FOREIGN KEY(actor_id) REFERENCES users(id));
